def count_Substrings(s):
    n = len(s)
    ans = 0
    for i in range(n):
        for j in range(i, n):
            length = j - i + 1
            digit_sum = sum(int(s[k]) for k in range(i, j + 1))
            if digit_sum == length:
                ans += 1
    return ans
```

