def bell_number(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 3
    B = [1] * (n + 1)
    for i in range(2, n + 1):
        next_B = [0] * (n + 1)
        s = 0
        for j in range(i):
            s += B[j]
        next_B[i] = s
        for j in range(i):
            next_B[j] = B[j]
        B = next_B
    return B[n]
```

