def next_smallest_palindrome(num):
    if num == 99:
        return 101
    s = str(num)
    n = len(s)
    half = n // 2
    left = s[:half]
    right = s[half:] if n % 2 == 0 else s[half+1:]

    def mirror(l):
        return l + l[::-1] if n % 2 == 0 else l + l[-2::-1]

    cand = int(mirror(left))
    if cand > num:
        return cand

    # try incrementing the left half
    inc = left
    while True:
        inc = str(int(inc) + 1)
        if len(inc) > half:
            # overflow of half, e.g. 99 -> 100
            return int('1' + '0'*(n-1) + '1')
        cand = int(mirror(inc))
        if cand > num:
            return cand
```

