def check_integer(text):
    # Strip whitespace
    s = text.strip()
    if not s:
        return False
    # Allow optional leading sign
    if s[0] in '+-':
        s = s[1:]
        if not s:
            return False
    # Now every character must be a digit
    return all(c in '0123456789' for c in s)
```

