def search(arr):
    n = len(arr)
    if n == 0:
        raise ValueError("Input array must contain at least one element.")
    if n == 1:
        return arr[0]
    if arr[0] != arr[1]:
        return arr[0]
    if arr[n-2] != arr[n-1]:
        return arr[n-1]

    low, high = 1, n - 2
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] != arr[mid-1] and arr[mid] != arr[mid+1]:
            return arr[mid]
        if arr[mid] == arr[mid+1]:
            low = mid + 2
        else:
            high = mid - 2
    raise ValueError("No unique element found.")
```

