def find_length(s):
    n = len(s)
    # Prefix sums: +1 for '0', -1 for '1'
    pref = [0] * (n + 1)
    for i, ch in enumerate(s):
        pref[i + 1] = pref[i] + (1 if ch == '0' else -1)

    max_diff = 0
    for i in range(n):
        for j in range(i, n):
            diff = pref[j + 1] - pref[i]
            if diff > max_diff:
                max_diff = diff
    return max_diff
```

