def find_length(s: str) -> int:
    if not s:
        return 0
    # Transform: 0 -> +1, 1 -> -1
    # We want the max subarray sum of this transformed array.
    max_diff = 0
    cur = 0
    for ch in s:
        cur += (1 if ch == '0' else -1)
        if cur > max_diff:
            max_diff = cur
        if cur < 0:
            cur = 0
    return max_diff
```

