def find_solution(a, b, n):
    # Handle the trivial case where n is 0
    if n == 0:
        return (0, 0)

    # For negative n, flip signs and remember to negate the result later
    negative = False
    if n < 0:
        negative = True
        n = -n
        a, b = -a, -b

    # For a and b that are both negative, make them positive for the loop
    if a < 0:
        a = -a
    if b < 0:
        b = -b

    # Brute-force search for a solution x such that (n - a*x) is divisible by b
    i = 0
    while i * a <= n:
        if (n - i * a) % b == 0:
            y = (n - i * a) // b
            if negative:
                return (-i, -y)
            return (i, y)
        i = i + 1

    return None
```

