def find_solution(a, b, n):
    if a <= 0 and b <= 0:
        return None
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None
    if a < 0:
        return find_solution(-a, b, n)
    if b < 0:
        return find_solution(a, -b, n)
    if n < 0:
        return find_solution(a, b, -n) if (a + b) % 2 == 0 else None
    if a > n:
        return (0, n // b) if n % b == 0 else None
    if b > n:
        return (n // a, 0) if n % a == 0 else None
    if a == b:
        return (n // a, 0) if n % a == 0 else None
    if a == 1 or b == 1:
        return (n, 0)
    if a + b == n:
        return (1, 1)
    if n - a >= 0 and (n - a) % b == 0:
        return (1, (n - a) // b)
    if n - b >= 0 and (n - b) % a == 0:
        return ((n - b) // a, 1)
    return None
