def div_sum(n):
    if n == 0:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            j = n // i
            if j != i:
                total += j
        i += 1
    return total

def are_equivalent(num1, num2):
    return div_sum(num1) == div_sum(num2)
