def is_majority(arr, n, x):
    def binary_search(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if arr[mid] == x:
                # First occurrence
                if mid == 0 or arr[mid - 1] != x:
                    return mid
                else:
                    return binary_search(arr, low, mid - 1, x)
            elif arr[mid] < x:
                return binary_search(arr, mid + 1, high, x)
            else:
                return binary_search(arr, low, mid - 1, x)
        return -1

    if n == 0:
        return False
    idx = binary_search(arr, 0, n - 1, x)
    if idx == -1:
        return False
    count = idx + (n - 1 - idx)
    return count > n // 2
