def is_majority(arr, n, x):
    if n % 2 == 1:
        mid = n // 2
        if arr[mid] != x:
            return False
        cnt = 1
        i = mid + 1
        while i < n and arr[i] == x:
            cnt += 1
            i += 1
        j = mid - 1
        while j >= 0 and arr[j] == x:
            cnt += 1
            j -= 1
        return cnt > n // 2
    else:
        if arr[n // 2 - 1] == x and arr[n // 2] == x:
            cnt = 2
            i = n // 2 + 1
            while i < n and arr[i] == x:
                cnt += 1
                i += 1
            j = n // 2 - 2
            while j >= 0 and arr[j] == x:
                cnt += 1
                j -= 1
            return cnt > n // 2
        return False
