            mid = (low + high) // 2
            if arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return low

    def binary_search_right(arr, low, high, x):
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] > x:
                high = mid - 1
            else:
                low = mid + 1
        return high - 1

    left = binary_search_left(arr, 0, n-1, x)
    if left == n:
        return False
    right = binary_search_right(arr, left, n-1, x)
    count = right - left + 1
    return count > n // 2
