def is_majority(arr, n, x):
    # In a sorted array, if x is the majority, it must occupy the middle position.
    if arr[n // 2] != x:
        return False
    # Count occurrences of x (they are contiguous in a sorted array)
    left, right = n // 2 - 1, n // 2 + 1
    while left >= 0 and arr[left] == x:
        left -= 1
    while right < n and arr[right] == x:
        right += 1
    count = right - left - 1
    return count > n // 2

