def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    # dp[i][k] = number of sequences of length k ending with value i
    dp = [0] * (m + 1)
    # For length 1, each value 1..m is a valid sequence of length 1
    for i in range(1, m + 1):
        dp[i] = 1

    total = 0
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        for i in range(1, m + 1):
            start = (i + 1) // 2
            for j in range(start, i + 1):
                new_dp[j] += dp[i]
        dp = new_dp

    for i in range(1, m + 1):
        total += dp[i]

    return total
```

