def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if m < 1:
        return 0

    # dp[i][j] = number of valid sequences of length j ending with value i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequences of length 1
    for i in range(1, m + 1):
        dp[i][1] = 1

    for length in range(2, n + 1):
        for current in range(1, m + 1):
            lower = (current + 1) // 2  # smallest previous value x with 2*x <= current
            for prev in range(lower, current):
                dp[current][length] += dp[prev][length - 1]

    total = sum(dp[i][n] for i in range(1, m + 1))
    return total
```

