def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1

    for length in range(2, n + 1):
        for start in range(1, m + 1):
            if start < 2:
                continue
            prev_max = start // 2
            if prev_max == 0:
                continue
            total = 0
            for prev in range(prev_max, start - 1):
                total += dp[prev][length - 1]
            dp[start][length] = total

    return dp[m][n]
```

