def max_sum(arr):
    if not arr:
        return 0

    n = len(arr)
    inc = [1] * n
    dec = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # For each peak, the sum is:
    #   max sum of increasing subsequence ending at i
    # + max sum of decreasing subsequence starting at i
    # - arr[i] (to avoid double counting the peak)
    best = 0
    for i in range(n):
        # Compute max sum increasing ending at i
        best_inc = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                best_inc = max(best_inc, inc[j] * arr[j] + arr[i])
        # Compute max sum decreasing starting at i
        best_dec = arr[i]
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                best_dec = max(best_dec, dec[j] * arr[j] + arr[i])
        best = max(best, best_inc + best_dec - arr[i])

    return best
```

