def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Increasing subsequence sums ending at i
    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Decreasing subsequence sums starting at i
    dec = arr[:]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    best = 0
    for i in range(n):
        best = max(best, inc[i] + dec[i] - arr[i])
    return best
