def max_sum(arr): 
    if not arr:
        return 0
    n = len(arr)
    # LIS ending at i
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # LDS starting at i (i.e., LIS on reversed suffix)
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    best = 0
    for i in range(n):
        val = arr[i]
        # count of elements in increasing part + count in decreasing part - 1 (to avoid double-counting peak)
        total = val * (inc[i] + dec[i] - 1)
        best = max(best, total)
    return best
