def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    inc = [0] * n
    dec = [0] * n

    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    for i in range(n):
        dec[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

