def count_Primes_nums(n):
    def is_prime(k):
        if k <= 1:
            return False
        if k <= 3:
            return True
        if k % 2 == 0 or k % 3 == 0:
            return False
        i = 5
        while i * i <= k:
            if k % i == 0 or k % (i + 2) == 0:
                return False
            i += 6
        return True

    return sum(1 for x in range(n) if is_prime(x))
