def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    SAME = k          # ways where last two posts have same color
    DIFF = k * (k - 1) # ways where last two posts differ

    for _ in range(3, n + 1):
        new_DIFF = DIFF * (k - 1) + SAME * (k - 1)
        SAME = DIFF
        DIFF = new_DIFF

    return (SAME + DIFF) % 1_000_000_007
```

