def sumofFactors(n):
    if n % 2 != 0:
        return 0
    total = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            s = 1
            t = 1
            while n % d == 0:
                n //= d
                t *= d
                s += t
            total *= s
        d += 1
    if n > 1:
        total *= (1 + n)
    return total
```

