import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find u, v such that a*u + b*v = g
    def egcd(x, y):
        if y == 0:
            return (1, 0)
        u, v = egcd(y, x % y)
        return (v, u - (x // y) * v)

    u, v = egcd(a, b)
    # Scale the solution to match n
    factor = n // g
    x0 = u * factor
    y0 = v * factor

    # Adjust to minimal non-negative x in [0, |b/g|)
    x0 = x0 % (b // g)
    y0 = (n - a * x0) // b

    return (x0, y0)
```

