import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a //= g
    b //= g
    n //= g
    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = 1
    def egcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = egcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)
    x0, y0 = egcd(a, b)
    # General solution: x = x0 * n + k * b, y = y0 * n - k * a
    # Choose k to make x non-negative
    k = (a - x0 * n) // b
    x = x0 * n + k * b
    y = y0 * n - k * a
    return (x, y)
```

