def is_majority(arr, n, x):
    if n <= 0:
        return False
    # In a sorted array, if x is majority, it must occupy the middle position.
    if arr[n // 2] != x:
        return False
    # Count occurrences of x using binary search for first and last index.
    def first_ge(arr, n, val):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < val:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def last_le(arr, n, val):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] > val:
                hi = mid
            else:
                lo = mid + 1
        return lo - 1

    first = first_ge(arr, n, x)
    if first == n:
        return False
    last = last_le(arr, n, x)
    return (last - first + 1) > n // 2
```

