def is_majority(arr, n, x):
    if n <= 0:
        return False
    if arr[0] == x:
        return arr[n // 2] == x
    if arr[-1] == x:
        return arr[n // 2] == x
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            left = mid + 1
            break
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    if left >= n or arr[left] != x:
        return False
    count = 0
    for i in range(left, n):
        if arr[i] == x:
            count += 1
        else:
            break
    return count > n // 2
```

