def next_smallest_palindrome(n: int) -> int:
    """Return the smallest palindrome strictly greater than n."""
    # Work with the next length if n is already a palindrome or at the max of its length
    s = str(n)
    L = len(s)

    # Try to construct a palindrome by mirroring the left half
    half = s[:L//2]
    if L % 2:
        half += s[L//2]

    # Mirror to get candidate
    if L % 2 == 1:
        cand = int(half + half[:-1][::-1])
    else:
        cand = int(half + half[::-1])

    if cand > n:
        return cand

    # Increment the left half and mirror again
    half_int = int(half) + 1
    half_str = str(half_int)
    if len(half_str) > len(half):
        # Overflow to next length, e.g. 99 -> 101
        return int('1' + '0' * (L - 1) + '1')

    if L % 2 == 1:
        cand = int(half_str + half_str[:-1][::-1])
    else:
        cand = int(half_str + half_str[::-1])

