def find_solution(a, b, n):
    import math
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a //= g
    b //= g
    n //= g
    # Extended Euclidean for a*x0 + b*y0 = 1
    def egcd(A, B):
        if B == 0:
            return (1, 0, A)
        x1, y1, g = egcd(B, A % B)
        return (y1, x1 - (A // B) * y1, g)
    x0, y0, _ = egcd(a, b)
    # x0, y0 satisfy a*x0 + b*y0 = 1, so for n:
    x = x0 * n
    y = y0 * n
    # Reduce x modulo b to get small solution
    x = x % b
    y = y - a * x
    return (x, y)
```

