def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    def gcd_extend(x, y, r):
        if y == 0:
            return (1, 0, x)
        d, t1, t2 = gcd_extend(y, x % y, x)
        return (t2, t1 - (x // y) * t2, d)

    d, t1, t2 = gcd_extend(a, b, 1)
    if n % d != 0:
        return None

    x0 = t1 * (n // d)
    y0 = t2 * (n // d)

    return (x0, y0)
