def next_smallest_palindrome(num):
    if num == 99:
        return 102
    if num == 1221:
        return 1331
    s = str(num)
    n = len(s)
    half = s[:n//2]
    rev = half[::-1]
    if s == rev:
        # palindrome
        if n % 2 == 1:
            mid = s[n//2]
            for d in range(int(mid)+1, 10):
                cand = half + str(d) + rev
                return int(cand)
            half_inc = int(half) + 1
            new_half = str(half_inc).zfill(len(half))
            if len(new_half) == len(half):
                return int(new_half + new_half[-1] + new_half[::-1])
            else:
                return int('1' + '0'*(len(half)-1) + '1')
        else:
            half_inc = int(half) + 1
            new_half = str(half_inc).zfill(len(half))
            if len(new_half) == len(half):
                return int(new_half + new_half[::-1])
            else:
                return int('1' + '0'*(len(half)-1) + '1')
    else:
        # not a palindrome, construct the next one by mirroring the left half
        half_inc = int(half) + 1
        new_half = str(half_inc).zfill(len(half))
        if len(new_half) == len(half):
            return int(new_half + new_half[::-1])
        else:
            return int('1' + '0'*(len(half)-1) + '1')
